const d = $json;
const brand = d.BrandKitKey || d.brandKitKey || {};
const input = $('Normalize Visual Brief').item.json;
const get = (k) => (d[k] !== undefined && d[k] !== null && d[k] !== '') ? d[k] : '';
const supplied = input.approved_brand_rules_override;
const context = supplied || [
  get('BrandRules') && `Brand rules: ${get('BrandRules')}`,
  get('Palette') && `Approved palette: ${get('Palette')}`,
  get('Typography') && `Approved typography: ${get('Typography')}`,
  get('LogoRules') && `Logo rules: ${get('LogoRules')}`,
  get('ImageStyle') && `Image style: ${get('ImageStyle')}`,
  get('Tone') && `Tone: ${get('Tone')}`
].filter(Boolean).join('\n');
const missing = [];
if (!context) missing.push('approved brand rules');
if (!get('Palette') && !/palette|colou?r/i.test(context)) missing.push('exact approved palette');
if (!get('Typography') && !/typograph|font/i.test(context)) missing.push('approved typography');
if (!get('LogoRules') && !/logo/i.test(context)) missing.push('logo usage rules');
return {json:{...input, brand_context: context || 'No approved brand-kit rules were found. Do not invent exact colors, fonts, or logo specifications.', missing_brand_specs: missing, brand_context_source: supplied ? 'request_override' : (context ? 'BrandKit sheet' : 'missing')}};

const response = $json;
const raw = response.choices?.[0]?.message?.content ?? response.body?.choices?.[0]?.message?.content ?? '';
const cleaned = String(raw).replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
let parsed, parseError = false;
try { parsed = JSON.parse(cleaned); } catch (e) { parsed = {raw_ai_draft: cleaned}; parseError = true; }
const required = ['master_prompt','prompt_variations','negative_prompt','layout_guidance','arabic_text_note','editing_checklist','required_human_checks','brand_specifications_missing'];
const missing = required.filter(k => !(k in parsed));
const variationsValid = Array.isArray(parsed.prompt_variations) && parsed.prompt_variations.length >= 1 && parsed.prompt_variations.every(v => v && typeof v.prompt === 'string' && v.prompt.trim().length > 20);
const masterValid = typeof parsed.master_prompt === 'string' && parsed.master_prompt.trim().length > 20;
const input = $('Build Prompt Context').item.json;
const validationErrors = [];
if (parseError) validationErrors.push('AI response was not valid JSON');
if (missing.length) validationErrors.push('Missing fields: ' + missing.join(', '));
if (!masterValid) validationErrors.push('master_prompt missing or too short');
if (!variationsValid) validationErrors.push('prompt_variations must contain prompt text');
if (!input.visual_goal) validationErrors.push('visual_goal is required');
const now = new Date().toISOString();
const slug = String(input.campaign_name || 'prompt').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,45) || 'prompt';
const promptId = `${slug}-${input.request_id}`;
return {json:{
  prompt_id: promptId,
  request_id: input.request_id,
  campaign_name: input.campaign_name,
  visual_goal: input.visual_goal,
  platform: input.platform,
  format: input.format,
  brand_kit_key: input.brand_kit_key,
  brand_context_source: input.brand_context_source,
  missing_brand_specs: input.missing_brand_specs,
  prompt_payload: parsed,
  validation: {valid: validationErrors.length === 0, errors: validationErrors, checked_at: now},
  approval_status: validationErrors.length === 0 ? 'PENDING_HUMAN_REVIEW' : 'REJECTED_VALIDATION',
  version: Number(input.version || 1),
  parent_prompt_id: input.parent_prompt_id || '',
  created_at: now,
  updated_at: now,
  raw_ai_response: raw
}};

const d=$json;
const errors=[];
if(!d.prompt_id) errors.push('prompt_id is required');
if(!Number.isInteger(Number(d.version)) || Number(d.version)<1) errors.push('version must be a positive integer');
if(!['APPROVED','REVISION_REQUIRED','REJECTED'].includes(d.decision)) errors.push('decision must be APPROVED, REVISION_REQUIRED, or REJECTED');
return {json:{...d,review_valid:errors.length===0,review_errors:errors}};
